NCAS48E0.ol:
#############################
# FSSZMA_TEMP_THERM Unfiltered
#
# This function computes the FSS thermistor engineering value using the following calibration:
#                                        X - Co - 256
#  R = (5110 * (1+Cr)) * ---------------------------------------------
#                               161469 * (1+Cg) - (X-Co - 256)
#
# Ref:
# RIU pre-processing: SOL.S.ASTR.RS.00126 i16, SRS.PF.RIU.FUNC.0620 - SRS.PF.RIU.FUNC.0650
# RIU Cmd & TM Handbook: SOL.BPATRI.ICD.53759.6, sect 4.5.5
# AOCS processing: SOL.S.ASTR.RS.00157 i4, REQ-CAS-FSSUNIT-206
#
VAR_Cg := 0.01;
VAR_Co := 500;
VAR_Cr := 0.01;
VAR_coefTempTherm := NCAP089Z;
VAR_tempBiasTherm := NCAP08AR;
#
# Select RIU-A or B based on SCV
if (NCSD0PE4 == "IN_USE" ) then
    VAR_X := NRU02807.raw;
else
    VAR_X := NRU12807.raw;
endif; 
#
VAR_denominator := ((161469*(1+VAR_Cg))-(VAR_X - VAR_Co - 256));
VAR_numerator := (5110*(1+VAR_Cr)) * (VAR_X - VAR_Co - 256);
VAR_thermres := VAR_numerator/VAR_denominator;
VAR_tempThermUnfilt := (VAR_thermres*VAR_coefTempTherm)-(VAR_tempBiasTherm);
#
return (VAR_tempThermUnfilt);

